<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Business Owner membership</title><style>body{background:#f4f7fb;color:#17233c;font-family:Inter,Arial,sans-serif}.wrap{max-width:700px;margin:45px auto;padding:20px}.card{background:#fff;border:1px solid #e3e9f2;border-radius:16px;padding:28px}.field{margin-bottom:16px}label{display:block;font-weight:700;font-size:13px;margin-bottom:6px}input,select{box-sizing:border-box;width:100%;padding:11px;border:1px solid #d8e1ed;border-radius:9px}.btn{display:inline-block;padding:11px 16px;border:0;border-radius:9px;background:#397ef6;color:#fff;font-weight:700;text-decoration:none}.secondary{background:#fff;color:#40506b;border:1px solid #d8e1ed}.actions{display:flex;justify-content:flex-end;gap:10px}.notice{padding:12px;background:#fff5df;color:#8a5700;border-radius:9px;margin-bottom:16px}</style></head><body><main class="wrap"><h1>Become a Business Owner</h1><p>Submit your plan and payment details. Business tools are enabled only after an administrator verifies and approves the membership.</p>@if($membership)<div class="notice">Current request status: <strong>{{ucfirst($membership->membership_status)}}</strong></div>@endif @if($errors->any())<div class="notice">{{$errors->first()}}</div>@endif<form class="card" method="post" action="{{route('member.membership.store')}}">@csrf<div class="field"><label>Membership plan</label><select name="plan_id" required>@foreach($plans as $plan)<option value="{{$plan->id}}" @selected(old('plan_id',$membership?->plan_id)==$plan->id)>{{$plan->name}} — ₹{{number_format((float)$plan->fee,2)}}</option>@endforeach</select></div><div class="field"><label>Payment date</label><input type="date" name="payment_date" value="{{old('payment_date',optional($membership?->payment_date)->format('Y-m-d'))}}" required></div><div class="field"><label>Amount paid</label><input type="number" min="0.01" step="0.01" name="payment_amount" value="{{old('payment_amount',$membership?->payment_amount)}}" required></div><div class="field"><label>Payment method</label><select name="payment_method" required>@foreach(['upi'=>'UPI','bank_transfer'=>'Bank transfer','card'=>'Card','cheque'=>'Cheque','cash'=>'Cash','other'=>'Other'] as $value=>$label)<option value="{{$value}}" @selected(old('payment_method',$membership?->payment_method)===$value)>{{$label}}</option>@endforeach</select></div><div class="field"><label>Transaction / payment reference</label><input name="payment_reference" maxlength="150" value="{{old('payment_reference',$membership?->payment_reference)}}" required></div><div class="actions"><a class="btn secondary" href="{{route('dashboard.index')}}">Cancel</a><button class="btn">Submit request</button></div></form></main></body></html>
